package io.github.ningpp.compat;

/** Replacement for System.Security.Authentication.AuthenticationException (generated by CSharpToJava converter). */
public class AuthenticationException extends SystemException {
    public AuthenticationException() { super(); }
    public AuthenticationException(String message) { super(message); }
    public AuthenticationException(String message, Throwable cause) { super(message, cause); }
}
